using System.Security.Claims;
using System.Text.Json;
using InventorySystem.Controllers;
using InventorySystem.Core.Models;
using InventorySystem.Data;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
namespace InventorySystem.Tests;
public class GatePassGroupTests
{
    private static ApplicationDbContext Db()=>new(new DbContextOptionsBuilder<ApplicationDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).ConfigureWarnings(w=>w.Ignore(InMemoryEventId.TransactionIgnoredWarning)).Options);
    private static GatePassController Gate(ApplicationDbContext db)=>new(db){ControllerContext=new(){HttpContext=new DefaultHttpContext{User=new(new ClaimsIdentity([new Claim(ClaimTypes.Name,"QA")],"QA"))}}};
    private static JsonElement Data(IActionResult result)=>JsonSerializer.SerializeToElement(Assert.IsType<JsonResult>(result).Value);
    private static async Task Seed(ApplicationDbContext db){db.ItemCategory.AddRange(new ItemCategory{CategoryId=1,CategoryName="Raw A",GroupType="RawMaterial",IsActive=true},new ItemCategory{CategoryId=2,CategoryName="Raw B",GroupType="RawMaterial",IsActive=true},new ItemCategory{CategoryId=3,CategoryName="Finished",GroupType="FinishedGoods",IsActive=true},new ItemCategory{CategoryId=4,CategoryName="Disabled",GroupType="RawMaterial",IsActive=false});db.Items.AddRange(new Items{ItemID=1,CategoryID=1,ItemName="Paper A",ItemType="RawMaterial",StockUnit="kg",IsActive=true},new Items{ItemID=2,CategoryID=2,ItemName="Paper B",ItemType="RawMaterial",StockUnit="kg",IsActive=true},new Items{ItemID=3,CategoryID=3,ItemName="Box",ItemType="FinishedGoods",StockUnit="pcs",IsActive=true},new Items{ItemID=4,CategoryID=4,ItemName="Inactive group paper",ItemType="RawMaterial",StockUnit="kg",IsActive=true},new Items{ItemID=5,CategoryID=1,ItemName="Pins A",ItemType="RawMaterial",StockUnit="pcs",IsActive=true});await db.SaveChangesAsync();}
    private static GatePass Pass(string direction="Inward")=>new(){Direction=direction,GroupId=1,PartyName="Raw A",Lines=[new(){ItemId=1,Description="Paper A",Unit="kg",UnitPrice=12.5m,TotalQuantity=2}]};
    [Fact]
    public async Task GroupChoicesAndPartyChoicesExposeStableIdsWithoutCreatingAccounts(){using var db=Db();await Seed(db);var c=Gate(db);var groups=Data(await c.GetGroupOptions()).GetProperty("data");Assert.Equal(3,groups.GetArrayLength());Assert.DoesNotContain(groups.EnumerateArray(),g=>g.GetProperty("GroupId").GetInt32()==4);var rows=Data(await c.GetPartyOptions(type:"RawMaterial")).GetProperty("data");Assert.All(rows.EnumerateArray(),r=>Assert.True(r.GetProperty("GroupId").GetInt32()>0));Assert.Empty(db.Parties);}
    [Theory][InlineData(1,1)][InlineData(2,2)][InlineData(3,3)]
    public async Task LookupFiltersByExactGroupForRawAndFinishedItems(int groupId,long itemId){using var db=Db();await Seed(db);var c=Gate(db);var rows=Data(await c.GetItemOptions(groupId:groupId)).GetProperty("data");Assert.All(rows.EnumerateArray(),r=>Assert.Equal(groupId,r.GetProperty("GroupId").GetInt32()));Assert.Contains(rows.EnumerateArray(),r=>r.GetProperty("ItemId").GetInt64()==itemId);Assert.Empty(Data(await c.GetItemOptions(search:"Paper B",groupId:1)).GetProperty("data").EnumerateArray());}
    [Fact]
    public async Task PaginationAndTypeFiltersNeverExposeAnotherGroup(){using var db=Db();await Seed(db);for(var i=10;i<36;i++)db.Items.Add(new(){ItemID=i,CategoryID=1,ItemName="A "+i,ItemType="RawMaterial",StockUnit="kg",IsActive=true});await db.SaveChangesAsync();var c=Gate(db);foreach(var page in new[]{1,2})Assert.All(Data(await c.GetItemOptions(page:page,groupId:1)).GetProperty("data").EnumerateArray(),r=>Assert.Equal(1,r.GetProperty("GroupId").GetInt32()));Assert.Empty(Data(await c.GetItemOptions(type:"FinishedGoods",groupId:1)).GetProperty("data").EnumerateArray());Assert.IsType<BadRequestObjectResult>(await c.GetItemOptions(groupId:4));Assert.IsType<BadRequestObjectResult>(await c.GetItemOptions(groupId:999));Assert.IsType<BadRequestObjectResult>(await c.GetItemOptions(groupId:0));}
    [Theory][InlineData("Inward")][InlineData("Outward")]
    public async Task GroupPersistsAcrossSaveReopenEditAndPrint(string direction){using var db=Db();await Seed(db);var c=Gate(db);var m=Pass(direction);Assert.IsType<OkObjectResult>(await c.Save(m));var saved=await db.GatePasses.Include(g=>g.Lines).SingleAsync();Assert.Equal(1,saved.GroupId);var data=Data(await c.GetById(saved.Id));Assert.Equal(1,data.GetProperty("GroupId").GetInt32());Assert.Equal(1,data.GetProperty("Lines")[0].GetProperty("ItemGroupId").GetInt32());m.Id=saved.Id;m.Revision=saved.Revision;m.Lines[0].Id=saved.Lines[0].Id;m.Remarks="Edited";Assert.IsType<OkObjectResult>(await c.Save(m));Assert.Equal(1,saved.GroupId);Assert.Equal(2,Assert.Single(saved.Lines).TotalQuantity);Assert.IsType<ViewResult>(await c.Print(saved.Id));Assert.Empty(db.Stock);Assert.Empty(db.AccountLedger);}
    [Theory][InlineData(2)][InlineData(3)][InlineData(999)]
    public async Task ForeignAndUnavailableItemsCannotBeSavedIntoSelectedGroup(long item){using var db=Db();await Seed(db);var m=Pass();m.Lines[0].ItemId=item;Assert.IsType<BadRequestObjectResult>(await Gate(db).Save(m));Assert.Empty(db.GatePasses);}
    [Fact]
    public async Task ManualDescriptionsCannotBypassSelectedGroupAndGroupCannotBeCleared(){using var db=Db();await Seed(db);var c=Gate(db);var m=Pass();m.Lines[0].ItemId=null;Assert.IsType<BadRequestObjectResult>(await c.Save(m));m=Pass();Assert.IsType<OkObjectResult>(await c.Save(m));var saved=await db.GatePasses.Include(g=>g.Lines).SingleAsync();m.Id=saved.Id;m.Revision=saved.Revision;m.GroupId=null;Assert.IsType<BadRequestObjectResult>(await c.Save(m));Assert.Equal(1,saved.GroupId);}
    [Fact]
    public async Task ChangingGroupRequiresMatchingItemsAndReplacesGroupAtomically(){using var db=Db();await Seed(db);var c=Gate(db);var m=Pass();Assert.IsType<OkObjectResult>(await c.Save(m));var saved=await db.GatePasses.Include(g=>g.Lines).SingleAsync();m.Id=saved.Id;m.Revision=saved.Revision;m.GroupId=2;Assert.IsType<BadRequestObjectResult>(await c.Save(m));Assert.Equal(1,saved.GroupId);m.Lines[0].ItemId=2;Assert.IsType<OkObjectResult>(await c.Save(m));Assert.Equal(2,saved.GroupId);Assert.Equal(2,Assert.Single(saved.Lines).ItemId);}
    [Fact]
    public async Task InactiveSavedGroupsRemainReadableButRejectNewItemsAndRespectBranchScope(){using var db=Db();await Seed(db);var c=Gate(db);var m=Pass();Assert.IsType<OkObjectResult>(await c.Save(m));var saved=await db.GatePasses.Include(g=>g.Lines).SingleAsync();m.Id=saved.Id;m.Revision=saved.Revision;m.Lines[0].Id=saved.Lines[0].Id;(await db.ItemCategory.FindAsync(1))!.IsActive=false;await db.SaveChangesAsync();Assert.Contains(Data(await c.GetGroupOptions(saved.Id)).GetProperty("data").EnumerateArray(),g=>g.GetProperty("GroupId").GetInt32()==1);Assert.IsType<OkObjectResult>(await c.Save(m));m.Revision=saved.Revision;m.Lines.Add(new(){ItemId=5,Description="Pins A",Unit="pcs",TotalQuantity=3});Assert.IsType<BadRequestObjectResult>(await c.Save(m));db.RestrictBranches=true;db.AllowedBranchIds=[2];Assert.DoesNotContain(Data(await c.GetGroupOptions(saved.Id)).GetProperty("data").EnumerateArray(),g=>g.GetProperty("GroupId").GetInt32()==1);}
}
